using System;
using System.Data;
using System.Globalization;
using System.Text;
using System.Web.UI;
using InformationWebObject;

namespace InformationCMS.Controls.DangKy
{
    /// <summary>
    /// Quản lý danh sách đăng ký tư vấn tiêm chủng.
    /// Chỉ yêu cầu đăng nhập CMS, không kiểm tra quyền riêng.
    /// </summary>
    public partial class DangKyTimChung : System.Web.UI.UserControl
    {
        private const byte StatusNew = 1;
        private const byte StatusProcessed = 2;

        private int PageIndex
        {
            get { return (ViewState["PageIndex"] == null) ? 1 : Convert.ToInt32(ViewState["PageIndex"]); }
            set { ViewState["PageIndex"] = value; }
        }

        private int PageSize
        {
            get
            {
                int pageSize;
                if (int.TryParse(ddlPageSize.SelectedValue, out pageSize) && pageSize > 0)
                    return pageSize;
                return 20;
            }
        }

        protected void Page_Load(object sender, EventArgs e)
        {
            if (!IsPostBack)
            {
                PageIndex = 1;
                BindData();
            }
        }

        protected string GetStatusBadge(object statusValue)
        {
            byte status = Convert.ToByte(statusValue);
            if (status == StatusProcessed)
                return "<span class='badge text-bg-success'>Đã xử lý</span>";
            return "<span class='badge text-bg-primary'>Mới</span>";
        }

        protected string GetToggleText(object statusValue)
        {
            byte status = Convert.ToByte(statusValue);
            if (status == StatusProcessed)
                return "Đánh dấu mới";
            return "Đã xử lý";
        }

        private DateTime? ParseDate(string yyyyMmDd)
        {
            if (string.IsNullOrWhiteSpace(yyyyMmDd))
                return null;

            DateTime parsedDate;
            if (DateTime.TryParseExact(yyyyMmDd.Trim(), "yyyy-MM-dd", CultureInfo.InvariantCulture, DateTimeStyles.None, out parsedDate))
                return parsedDate;

            return null;
        }

        private object GetStatusParam()
        {
            string selectedStatus = (ddlStatus.SelectedValue ?? string.Empty).Trim();
            if (selectedStatus == string.Empty)
                return DBNull.Value;

            return Convert.ToByte(selectedStatus);
        }

        private DataTable GetRegisterData(int pageIndex, int pageSize)
        {
            string keyword = (txtKeyword.Text ?? string.Empty).Trim();
            DateTime? fromDate = ParseDate(txtFromDate.Text);
            DateTime? toDate = ParseDate(txtToDate.Text);

            INFO_TiemChungRegister objRegister = new INFO_TiemChungRegister();
            return objRegister.Search(
                "@Keyword", string.IsNullOrWhiteSpace(keyword) ? (object)DBNull.Value : keyword,
                "@FromDate", fromDate.HasValue ? (object)fromDate.Value : DBNull.Value,
                "@ToDate", toDate.HasValue ? (object)toDate.Value : DBNull.Value,
                "@Status", GetStatusParam(),
                "@PageIndex", pageIndex,
                "@PageSize", pageSize
            );
        }

        private void BindData()
        {
            DataTable dt = GetRegisterData(PageIndex, PageSize);

            int totalRows = 0;
            if (dt != null && dt.Rows.Count > 0 && dt.Columns.Contains("TotalRows"))
                totalRows = Convert.ToInt32(dt.Rows[0]["TotalRows"]);

            int totalPage = (totalRows <= 0) ? 1 : (int)Math.Ceiling(totalRows / (double)PageSize);
            if (PageIndex > totalPage)
                PageIndex = totalPage;

            litTotal.Text = totalRows.ToString("N0", CultureInfo.InvariantCulture);
            litPage.Text = PageIndex.ToString(CultureInfo.InvariantCulture);
            litTotalPage.Text = totalPage.ToString(CultureInfo.InvariantCulture);

            btnPrev.Enabled = PageIndex > 1;
            btnNext.Enabled = PageIndex < totalPage;

            rpt.DataSource = dt;
            rpt.DataBind();

            phEmpty.Visible = (dt == null || dt.Rows.Count == 0);
            udp.Update();
        }

        protected void btnSearch_Click(object sender, EventArgs e)
        {
            PageIndex = 1;
            BindData();
        }

        protected void btnClear_Click(object sender, EventArgs e)
        {
            txtKeyword.Text = string.Empty;
            txtFromDate.Text = string.Empty;
            txtToDate.Text = string.Empty;
            ddlStatus.SelectedValue = string.Empty;
            ddlPageSize.SelectedValue = "20";
            PageIndex = 1;
            BindData();
        }

        protected void btnPrev_Click(object sender, EventArgs e)
        {
            if (PageIndex > 1)
                PageIndex--;
            BindData();
        }

        protected void btnNext_Click(object sender, EventArgs e)
        {
            PageIndex++;
            BindData();
        }

        protected void ddlPageSize_SelectedIndexChanged(object sender, EventArgs e)
        {
            PageIndex = 1;
            BindData();
        }

        protected void btnToggleStatus_Click(object sender, EventArgs e)
        {
            string[] parts = ((System.Web.UI.WebControls.LinkButton)sender).CommandArgument.Split('|');
            int registerId = Convert.ToInt32(parts[0]);
            byte currentStatus = parts.Length > 1 ? Convert.ToByte(parts[1]) : StatusNew;
            byte newStatus = currentStatus == StatusProcessed ? StatusNew : StatusProcessed;

            INFO_TiemChungRegister objRegister = new INFO_TiemChungRegister(registerId);
            if (objRegister.TiemChungRegisterID == null || objRegister.TiemChungRegisterID.Value <= 0)
            {
                ShowMessage("Không tìm thấy đăng ký.", false);
                return;
            }

            objRegister.Status = newStatus;
            if (objRegister.Update())
                ShowMessage(newStatus == StatusProcessed ? "Đã đánh dấu đã xử lý." : "Đã đánh dấu mới.", true);
            else
                ShowMessage("Không thể cập nhật trạng thái.", false);

            BindData();
        }

        protected void btnDelete_Click(object sender, EventArgs e)
        {
            int registerId = Convert.ToInt32(((System.Web.UI.WebControls.LinkButton)sender).CommandArgument);
            INFO_TiemChungRegister objRegister = new INFO_TiemChungRegister();
            if (objRegister.Delete(registerId))
                ShowMessage("Đã xóa đăng ký.", true);
            else
                ShowMessage("Không thể xóa đăng ký.", false);

            BindData();
        }

        protected void btnExport_Click(object sender, EventArgs e)
        {
            DataTable dt = GetRegisterData(1, 100000);
            if (dt == null || dt.Rows.Count == 0)
            {
                ShowMessage("Không có dữ liệu để xuất.", false);
                return;
            }

            string fileName = "DangKy-TiemChung-" + DateTime.Now.ToString("yyyyMMddHHmmss") + ".csv";
            StringBuilder sb = new StringBuilder();
            sb.AppendLine("ID;HoTen;DienThoai;Email;NoiDung;TrangThai;IP;NgayDangKy");

            foreach (DataRow row in dt.Rows)
            {
                sb.AppendLine(string.Format("{0};{1};{2};{3};{4};{5};{6};{7}",
                    row["TiemChungRegisterID"],
                    CsvEscape(row["FullName"]),
                    CsvEscape(row["Phone"]),
                    CsvEscape(row["Email"]),
                    CsvEscape(row["Content"]),
                    Convert.ToByte(row["Status"]) == StatusProcessed ? "Da xu ly" : "Moi",
                    CsvEscape(row["ClientIP"]),
                    row["CreatedDate"] != DBNull.Value ? Convert.ToDateTime(row["CreatedDate"]).ToString("yyyy-MM-dd HH:mm") : string.Empty));
            }

            Page.Response.Clear();
            Page.Response.ContentType = "text/csv";
            Page.Response.ContentEncoding = Encoding.UTF8;
            Page.Response.AppendHeader("Content-Disposition", "attachment;filename=" + fileName);
            Page.Response.Write("\uFEFF");
            Page.Response.Write(sb.ToString());
            Page.Response.End();
        }

        private string CsvEscape(object value)
        {
            if (value == null || value == DBNull.Value)
                return string.Empty;

            string text = Convert.ToString(value).Replace("\"", "\"\"");
            if (text.IndexOf(';') >= 0 || text.IndexOf('"') >= 0 || text.IndexOf('\n') >= 0 || text.IndexOf('\r') >= 0)
                return "\"" + text + "\"";

            return text;
        }

        private void ShowMessage(string message, bool isSuccess)
        {
            string cssClass = isSuccess ? "alert alert-success" : "alert alert-danger";
            string script = string.Format(
                "alert('{0}');",
                message.Replace("'", "\\'")
            );
            ScriptManager.RegisterStartupScript(Page, Page.GetType(), "DangKyTimChungMsg", script, true);
        }
    }
}

