protected void btnExport_Click(object sender, EventArgs e)
{
    DataTable dt = GetRegisterData(1, 100000);
    if (dt == null || dt.Rows.Count == 0)
    {
        ShowMessage("Không có dữ liệu để xuất.", false);
        return;
    }

    string fileName = "DangKy-TiemChung-" + DateTime.Now.ToString("yyyyMMddHHmmss") + ".csv";
    StringBuilder sb = new StringBuilder();
    sb.AppendLine("ID;HoTen;DienThoai;Email;NoiDung;TrangThai;IP;NgayDangKy");

    foreach (DataRow row in dt.Rows)
    {
        sb.AppendLine(string.Format("{0};{1};{2};{3};{4};{5};{6};{7}",
            row["TiemChungRegisterID"],
            CsvEscape(row["FullName"]),
            CsvEscape(row["Phone"]),
            CsvEscape(row["Email"]),
            CsvEscape(row["Content"]),
            Convert.ToByte(row["Status"]) == StatusProcessed ? "Da xu ly" : "Moi",
            CsvEscape(row["ClientIP"]),
            row["CreatedDate"] != DBNull.Value ? Convert.ToDateTime(row["CreatedDate"]).ToString("yyyy-MM-dd HH:mm") : string.Empty));
    }

    Page.Response.Clear();
    Page.Response.ContentType = "text/csv";
    Page.Response.ContentEncoding = Encoding.UTF8;
    Page.Response.AppendHeader("Content-Disposition", "attachment;filename=" + fileName);
    Page.Response.Write("\uFEFF");
    Page.Response.Write(sb.ToString());
    Page.Response.End();
}

private string CsvEscape(object value)
{
    if (value == null || value == DBNull.Value)
        return string.Empty;

    string text = Convert.ToString(value).Replace("\"", "\"\"");
    if (text.IndexOf(';') >= 0 || text.IndexOf('"') >= 0 || text.IndexOf('\n') >= 0 || text.IndexOf('\r') >= 0)
        return "\"" + text + "\"";

    return text;
}

